assert len(source) == 64623
assert sha256(source).hexdigest() == 'aeda1290070e9c70de139e0e24238ce5b91359fd334948f72f2a2b02034a48be'
if __name__ == "__main__":
    sys.stdout.buffer.write(source)
else:
    exec(compile(source, __file__, "exec"), globals())
